from collections import deque

def minimum_obstacles(grid):
    R, C = len(grid), len(grid[0])
    INF = float('inf')
    d = [[INF] * C for _ in range(R)]
    d[0][0] = 0
    q = deque([(0, 0)])
    while q:
        y, x = q.popleft()
        for yy, xx in ((y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)):
            if 0 <= yy < R and 0 <= xx < C:
                w = grid[yy][xx]
                if d[y][x] + w < d[yy][xx]:
                    d[yy][xx] = d[y][x] + w
                    if w:
                        q.append((yy, xx))
                    else:
                        q.appendleft((yy, xx))
    return d[R - 1][C - 1]

