int minimumObstacles(vector<vector<int>>& g) {
    int R = g.size(), C = g[0].size(); vector<vector<int>> d(R, vector<int>(C, INT_MAX)); d[0][0] = 0; deque<pair<int,int>> q{{0, 0}}; int dd[5] = {1, 0, -1, 0, 1};
    while (!q.empty()) { auto [y, x] = q.front(); q.pop_front();
        for (int k = 0; k < 4; k++) { int yy = y + dd[k], xx = x + dd[k + 1]; if (yy < 0 || yy >= R || xx < 0 || xx >= C) continue; int w = g[yy][xx];
            if (d[y][x] + w < d[yy][xx]) { d[yy][xx] = d[y][x] + w; if (w) q.push_back({yy, xx}); else q.push_front({yy, xx}); } } }
    return d[R - 1][C - 1];
}
